//! Constant tables transcribed from Rec. ITU-T H.265 (V11, 01/2026) or generated from the
//! formulas the specification gives. Each table names its source clause.

/// Up-right diagonal scan (clause 6.5.3), generated by the algorithm (6-11).
const fn diag_scan<const N: usize, const NN: usize>() -> [(u8, u8); NN] {
    let mut out = [(0u8, 0u8); NN];
    let mut i = 0usize;
    let mut x: i32 = 0;
    let mut y: i32 = 0;
    loop {
        while y >= 0 {
            if (x as usize) < N && (y as usize) < N {
                out[i] = (x as u8, y as u8);
                i += 1;
            }
            y -= 1;
            x += 1;
        }
        y = x;
        x = 0;
        if i >= NN {
            break;
        }
    }
    out
}

/// Horizontal scan (clause 6.5.4).
const fn hor_scan<const N: usize, const NN: usize>() -> [(u8, u8); NN] {
    let mut out = [(0u8, 0u8); NN];
    let mut i = 0;
    let mut y = 0;
    while y < N {
        let mut x = 0;
        while x < N {
            out[i] = (x as u8, y as u8);
            i += 1;
            x += 1;
        }
        y += 1;
    }
    out
}

/// Vertical scan (clause 6.5.5).
const fn ver_scan<const N: usize, const NN: usize>() -> [(u8, u8); NN] {
    let mut out = [(0u8, 0u8); NN];
    let mut i = 0;
    let mut x = 0;
    while x < N {
        let mut y = 0;
        while y < N {
            out[i] = (x as u8, y as u8);
            i += 1;
            y += 1;
        }
        x += 1;
    }
    out
}

pub const DIAG_SCAN_2X2: [(u8, u8); 4] = diag_scan::<2, 4>();
pub const DIAG_SCAN_4X4: [(u8, u8); 16] = diag_scan::<4, 16>();
pub const DIAG_SCAN_8X8: [(u8, u8); 64] = diag_scan::<8, 64>();
pub const HOR_SCAN_2X2: [(u8, u8); 4] = hor_scan::<2, 4>();
pub const HOR_SCAN_4X4: [(u8, u8); 16] = hor_scan::<4, 16>();
pub const VER_SCAN_2X2: [(u8, u8); 4] = ver_scan::<2, 4>();
pub const VER_SCAN_4X4: [(u8, u8); 16] = ver_scan::<4, 16>();
pub const SINGLE: [(u8, u8); 1] = [(0, 0)];

/// Sub-block scans indexed by [log2TrafoSize - 2][scanIdx] (ScanOrder[log2-2][scanIdx]).
pub fn sub_block_scan(log2_size_minus2: u32, scan_idx: u32) -> &'static [(u8, u8)] {
    match (log2_size_minus2, scan_idx) {
        (0, _) => &SINGLE,
        (1, 0) => &DIAG_SCAN_2X2,
        (1, 1) => &HOR_SCAN_2X2,
        (1, _) => &VER_SCAN_2X2,
        (2, _) => &DIAG_SCAN_4X4,
        _ => &DIAG_SCAN_8X8,
    }
}

/// Position-in-sub-block scans, ScanOrder[2][scanIdx], packed as (y << 2) | x.
pub const SCAN_POS_4X4: [[u8; 16]; 3] = {
    let mut out = [[0u8; 16]; 3];
    let mut i = 0;
    while i < 16 {
        out[0][i] = (DIAG_SCAN_4X4[i].1 << 2) | DIAG_SCAN_4X4[i].0;
        out[1][i] = (HOR_SCAN_4X4[i].1 << 2) | HOR_SCAN_4X4[i].0;
        out[2][i] = (VER_SCAN_4X4[i].1 << 2) | VER_SCAN_4X4[i].0;
        i += 1;
    }
    out
};

