/// sigCtx pattern (9-45 .. 9-48) for log2TrafoSize > 2, indexed by prevCsbf and the
/// in-sub-block position (yP << 2) | xP.
pub const SIG_PATTERN: [[u8; 16]; 4] = {
    let mut t = [[0u8; 16]; 4];
    let mut p = 0;
    while p < 16 {
        let xp = p & 3;
        let yp = p >> 2;
        t[0][p] = if xp + yp == 0 {
            2
        } else if xp + yp < 3 {
            1
        } else {
            0
        };
        t[1][p] = if yp == 0 {
            2
        } else if yp == 1 {
            1
        } else {
            0
        };
        t[2][p] = if xp == 0 {
            2
        } else if xp == 1 {
            1
        } else {
            0
        };
        t[3][p] = 2;
        p += 1;
    }
    t
};

/// Table 9-50 ctxIdxMap for 4x4 sig_coeff_flag.
pub const CTX_IDX_MAP: [u8; 16] = [0, 1, 4, 5, 2, 3, 4, 5, 6, 6, 8, 8, 7, 7, 8, 8];

/// sig_coeff_flag context increments in scan order: SIG_PATTERN[prevCsbf] looked up at
/// ScanOrder[2][scanIdx][n], indexed by [scanIdx][prevCsbf][n].
pub const SIG_CTX_SCAN: [[[u8; 16]; 4]; 3] = {
    let mut t = [[[0u8; 16]; 4]; 3];
    let mut s = 0;
    while s < 3 {
        let mut c = 0;
        while c < 4 {
            let mut k = 0;
            while k < 16 {
                t[s][c][k] = SIG_PATTERN[c][SCAN_POS_4X4[s][k] as usize];
                k += 1;
            }
            c += 1;
        }
        s += 1;
    }
    t
};

/// CTX_IDX_MAP in scan order, indexed by [scanIdx][n] (4x4 transform blocks).
pub const CTX_IDX_MAP_SCAN: [[u8; 16]; 3] = {
    let mut t = [[0u8; 16]; 3];
    let mut s = 0;
    while s < 3 {
        let mut k = 0;
        while k < 16 {
            t[s][k] = CTX_IDX_MAP[SCAN_POS_4X4[s][k] as usize];
            k += 1;
        }
        s += 1;
    }
    t
};

/// Inverse of SCAN_POS_4X4: scan index of in-sub-block position (yP << 2) | xP.
pub const SCAN_INV_4X4: [[u8; 16]; 3] = {
    let mut t = [[0u8; 16]; 3];
    let mut s = 0;
    while s < 3 {
        let mut k = 0;
        while k < 16 {
            t[s][SCAN_POS_4X4[s][k] as usize] = k as u8;
            k += 1;
        }
        s += 1;
    }
    t
};

const fn invert_scan<const NN: usize>(scan: &[(u8, u8); NN], w: usize) -> [u8; NN] {
    let mut t = [0u8; NN];
    let mut k = 0;
    while k < NN {
        t[scan[k].1 as usize * w + scan[k].0 as usize] = k as u8;
        k += 1;
    }
    t
}

const DIAG_INV_2X2: [u8; 4] = invert_scan(&DIAG_SCAN_2X2, 2);
const HOR_INV_2X2: [u8; 4] = invert_scan(&HOR_SCAN_2X2, 2);
const VER_INV_2X2: [u8; 4] = invert_scan(&VER_SCAN_2X2, 2);
const DIAG_INV_4X4: [u8; 16] = invert_scan(&DIAG_SCAN_4X4, 4);
const DIAG_INV_8X8: [u8; 64] = invert_scan(&DIAG_SCAN_8X8, 8);

/// Inverse of `sub_block_scan`: scan index of sub-block yS * width + xS.
pub fn sub_block_scan_inv(log2_size_minus2: u32, scan_idx: u32) -> &'static [u8] {
    match (log2_size_minus2, scan_idx) {
        (0, _) => &[0],
        (1, 0) => &DIAG_INV_2X2,
        (1, 1) => &HOR_INV_2X2,
        (1, _) => &VER_INV_2X2,
        (2, _) => &DIAG_INV_4X4,
        _ => &DIAG_INV_8X8,
    }
}

