/// Full 32x32 DCT matrix M[k][n] (frequency k, position n).
pub const TRANS_MATRIX: [[i8; 32]; 32] = {
    let mut m = [[0i8; 32]; 32];
    let mut k = 0;
    while k < 32 {
        let mut n = 0;
        while n < 16 {
            let v = TRANS_MATRIX_COL0TO15[k][n];
            m[k][n] = v;
            m[k][31 - n] = if k % 2 == 0 { v } else { -v };
            n += 1;
        }
        k += 1;
    }
    m
};

