/// Table 8-10 QpC as a function of qPi for ChromaArrayType == 1 (qPi 30..43; below 30 QpC = qPi,
/// above 43 QpC = qPi - 6).
pub fn qpc_from_qpi(qpi: i32) -> i32 {
    const T: [i8; 14] = [29, 30, 31, 32, 33, 33, 34, 34, 35, 35, 36, 36, 37, 37];
    if qpi < 30 {
        qpi
    } else if qpi > 43 {
        qpi - 6
    } else {
        T[(qpi - 30) as usize] as i32
    }
}

