#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn matrix_symmetry_matches_col16to31() {
        // Spot checks against equation 8-321 rows.
        assert_eq!(TRANS_MATRIX[1][16], -4);
        assert_eq!(
            TRANS_MATRIX[3][16..32],
            [
                13, 38, 61, 78, 88, 90, 85, 73, 54, 31, 4, -22, -46, -67, -82, -90
            ]
        );
        assert_eq!(
            TRANS_MATRIX[31][16..32],
            [
                90, -90, 88, -85, 82, -78, 73, -67, 61, -54, 46, -38, 31, -22, 13, -4
            ]
        );
        assert_eq!(
            TRANS_MATRIX[21][16..32],
            [
                -78, -4, 82, -73, -13, 85, -67, -22, 88, -61, -31, 90, -54, -38, 90, -46
            ]
        );
    }
    #[test]
    fn diag() {
        assert_eq!(DIAG_SCAN_4X4[0], (0, 0));
        assert_eq!(DIAG_SCAN_4X4[1], (0, 1));
        assert_eq!(DIAG_SCAN_4X4[2], (1, 0));
        assert_eq!(DIAG_SCAN_4X4[15], (3, 3));
    }
}
